import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { catalogueFile, ConfigError } from '@lakka/contracts';
import type { CatalogueFile, CatalogueModel } from '@lakka/contracts';

/*
 * The bundled model catalogue (PR-5, ADR 0037): generated by `pnpm catalogue:update`, committed,
 * and shipped in the image, so prices are known with no network access (NF-D5). It is validated
 * on load; an invalid file stops the process rather than billing with bad prices.
 *
 * A signed price feed, when an admin turned it on, can replace bundled entries and add models
 * (PR-6, ADR 0116). What a process prices with is read through a CatalogueStore, so the feed
 * can swap it while running; a request reads it once and keeps it to the end (pinCatalogue).
 */

export const BUNDLED_CATALOGUE_PATH = fileURLToPath(
  new URL('../../catalogue/models.json', import.meta.url),
);

export interface Catalogue {
  readonly source: Pick<CatalogueFile, 'source' | 'sourceCommit' | 'generatedAt'>;
  /** The release's serial, or the applied feed's. */
  readonly serial: number;
  /** The bundled models by id, with a newer feed's entries in place of the bundled ones. */
  readonly models: ReadonlyMap<string, CatalogueModel>;
  /** Models only the feed lists. They rank below custom models, so an admin's price wins. */
  readonly feedOnly: ReadonlyMap<string, CatalogueModel>;
  /** Models whose prices came from the feed and differ from the release's, and feed-only ones. */
  readonly priceUpdated: ReadonlySet<string>;
}

/** The models of a catalogue file by id; a duplicate is refused. */
export function modelsById(models: readonly CatalogueModel[]): Map<string, CatalogueModel> {
  const byId = new Map<string, CatalogueModel>();
  for (const model of models) {
    if (byId.has(model.id)) throw new ConfigError(`the model catalogue lists ${model.id} twice`);
    byId.set(model.id, model);
  }
  return byId;
}

export function parseCatalogue(json: unknown): Catalogue {
  const parsed = catalogueFile.safeParse(json);
  if (!parsed.success) {
    throw new ConfigError('the model catalogue is invalid', { cause: parsed.error });
  }
  const { serial, source, sourceCommit, generatedAt } = parsed.data;
  return {
    source: { source, sourceCommit, generatedAt },
    serial,
    models: modelsById(parsed.data.models),
    feedOnly: new Map(),
    priceUpdated: new Set(),
  };
}

export function loadCatalogue(path: string = BUNDLED_CATALOGUE_PATH): Catalogue {
  return parseCatalogue(JSON.parse(readFileSync(path, 'utf8')) as unknown);
}

/** Where the catalogue to price with is read from. */
export interface CatalogueStore {
  /** The catalogue that applies now. A request reads it once (pinCatalogue). */
  current(): Catalogue;
  /** The release's own catalogue, which a feed is checked against. */
  readonly bundled: Catalogue;
  /** Reads the feed's state now rather than at the next poll, after an admin changed it. */
  reload(): Promise<void>;
}

/** A store that always has the same catalogue: tests, scripts, and a request once pinned. */
export function fixedCatalogue(
  catalogue: Catalogue,
  bundled: Catalogue = catalogue,
): CatalogueStore {
  return { current: () => catalogue, bundled, reload: async () => undefined };
}

/**
 * The catalogue as it is now, kept for the rest of a request, so its estimate, reservation,
 * dispatch and usage rows all use the same prices even if a feed is applied meanwhile
 * (invariant 4, ADR 0116).
 */
export function pinCatalogue(store: CatalogueStore): CatalogueStore {
  return fixedCatalogue(store.current(), store.bundled);
}
